```jsx
import { useSelector, useDispatch } from 'react-redux';

const CartComponent = () => {
  const cartItems = useSelector(state => state.cart.items)
  const dispatch = useDispatch();

  return (
    <div>
      <h2>Shopping Cart</h2>
      <ul>
        {cartItems.map(item => (
          <li key={item.id}>
            {item.name} - ${item.price}
            <button onClick={() => dispatch({type: 'cart/removeItem', payload: item.id})}>
              Remove
            </button>
          </li>
        ))}
      </ul>
      <button onClick={() => dispatch({type: 'cart/addItem', payload: {id: 123, name: 'test', price: 9.99}})}>
        Add Test Item
      </button>
    </div>
  )
}
```

This assumes you have the cart slice properly setup in your store — it's not actually doing much beyond the example you wanted to see.

```jsx
const CartComponent = () => {
  const dispatch = useDispatch();
  const { items } = useSelector(state => state.cart);

  return (
    <div className="cart">
      {items.map(item => (
        <div key={item.id} className="cart-item">
          <span>{item.name}</span>
          <button onClick={() => dispatch(removeItem(item.id))}>Remove</button>
        </div>
      ))}
      <button onClick={() => dispatch(checkout())}>Checkout</button>
    </div>
  );
};
```

